<template><Teleport to="body"><div class="signed-overlay" role="dialog" aria-modal="true" :aria-label="item.label" @keydown.esc="$emit('close')" @contextmenu.prevent><header><strong>{{ item.label }}</strong><button ref="closeButton" @click="$emit('close')">Close</button></header><nav class="view-controls"><button :aria-pressed="mobile" @click="mobile=true">Mobile view</button><button :aria-pressed="!mobile" @click="mobile=false">Original A4</button></nav><div v-if="mobile" class="mobile-reading"><p class="reading-note">Agreement is signed and Now locked.</p><p v-if="loading">Loading signed document…</p><p v-if="error" role="alert">{{ error }}</p><iframe v-if="mobileHtml" class="reading-frame" :srcdoc="mobileHtml" sandbox="" :title="item.label"/><section v-for="(page,index) in (mobileHtml?[]:textPages)" :key="index"><p v-for="(line,n) in page.split('\n')" :key="n">{{ line }}</p></section></div><nav v-show="!mobile" class="zoom-controls" aria-label="Document zoom"><button @click="setZoom(zoom-.25)" :disabled="zoom<=1">−</button><span>{{ Math.round(zoom*100) }}%</span><button @click="setZoom(zoom+.25)" :disabled="zoom>=3">+</button><button @click="setZoom(1)">Fit width</button></nav><div v-show="!mobile" class="pages" ref="container" @touchstart="pinchStart" @touchmove="pinchMove" @touchend="pinchDistance=0"><p v-if="loading">Loading signed document…</p><p v-if="error" role="alert">{{ error }}</p></div></div></Teleport></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {frappeRequest} from 'frappe-ui'
import {getDocument,GlobalWorkerOptions} from 'pdfjs-dist'
import workerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url'
GlobalWorkerOptions.workerSrc=workerUrl
const props=defineProps({item:Object});defineEmits(['close'])
const mobile=ref(true),mobileHtml=ref(''),textPages=ref([])
const container=ref(null),closeButton=ref(null),loading=ref(true),error=ref('');let task,disposed=false;const zoom=ref(1.5);let fitWidth=0,pinchDistance=0,pinchZoom=1
function setZoom(value){zoom.value=Math.max(1,Math.min(3,value));container.value?.querySelectorAll('canvas').forEach(c=>c.style.width=fitWidth*zoom.value+'px')}
function pinchStart(e){if(e.touches.length===2){pinchDistance=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);pinchZoom=zoom.value}}
function pinchMove(e){if(e.touches.length===2&&pinchDistance){e.preventDefault();setZoom(pinchZoom*Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY)/pinchDistance)}}
onMounted(async()=>{closeButton.value.focus();try{const r=await frappeRequest({url:props.item.field==='peak_joining_2026'?'/api/method/onemotion.api.profile_peak_agreement.preview':'/api/method/onemotion.api.profile_agreement_pack.signed_documents',params:{field:props.item.field}});const data=r?.message??r;textPages.value=data.text_pages||[];mobileHtml.value=data.mobile_html||'';task=getDocument({data:Uint8Array.from(atob(data.pdf),c=>c.charCodeAt(0))});const pdf=await task.promise;for(let n=1;n<=pdf.numPages&&!disposed;n++){const page=await pdf.getPage(n);if(disposed)break;const viewport=page.getViewport({scale:1});fitWidth=Math.max(240,(container.value.clientWidth||window.innerWidth-16)-24);const scale=fitWidth/viewport.width;const view=page.getViewport({scale:scale*Math.max(2,devicePixelRatio)*1.5});const canvas=document.createElement('canvas');canvas.width=view.width;canvas.height=view.height;canvas.style.width=fitWidth*zoom.value+'px';canvas.setAttribute('aria-label',`Page ${n} of ${pdf.numPages}`);container.value.append(canvas);await page.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise}}catch{if(!disposed)error.value='Could not load the signed document. Close and try again.'}finally{loading.value=false}})
onBeforeUnmount(()=>{disposed=true;task?.destroy()})
</script>
<style scoped>.signed-overlay{position:fixed;inset:8px;z-index:20000;background:#eef1f5;border-radius:12px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 8px 40px #0005}.signed-overlay header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;background:white}.signed-overlay strong{font-size:.95rem}.signed-overlay button{background:#075da8;color:white;border-radius:8px;padding:10px 16px}.pages{overflow:auto;flex:1;padding:12px;overscroll-behavior:contain}.pages :deep(canvas){display:block;margin-bottom:12px;background:white}.zoom-controls{display:flex;align-items:center;justify-content:center;gap:12px;padding:8px;background:white;border-top:1px solid #e3e8ee}.zoom-controls button{min-width:40px;padding:8px 12px;background:#e5e7eb;color:#17202b}.pages{touch-action:pan-x pan-y}.pages :deep(canvas){max-width:none}.view-controls{display:flex;gap:8px;padding:8px 12px;background:white}.view-controls button{background:#edf1f5;color:#17202b}.view-controls button[aria-pressed="true"]{background:#075da8;color:white}.mobile-reading{overflow:auto;flex:1;padding:16px;background:white;font-size:16px;line-height:1.65;overflow-wrap:anywhere}.mobile-reading section p{margin:0 0 .65em}.reading-note{font-size:12px;color:#64748b;margin-bottom:20px}.mobile-reading:has(.reading-frame){display:flex;flex-direction:column;padding:0;overflow:hidden}.mobile-reading:has(.reading-frame) .reading-note{padding:8px 12px;margin:0;font-size:11px}.reading-frame{flex:1;min-height:0;width:100%;border:0;background:white}</style>
